<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('storage_locations') ?></h1>
<div class="<?= $canManage?'grid':'material-browser' ?>">
<?php if($canManage): ?><section class="card"><div class="toolbar"><h2><?= $editing?View::t('edit_location'):View::t('new_location') ?></h2><?php if($editing): ?><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/locations"><?= View::t('cancel') ?></a><?php endif; ?></div><form method="post" action="<?= View::e($basePath) ?><?= $editing?'/locations/'.View::e($editing['id']):'/locations' ?>"><?= View::csrf() ?><label><?= View::t('name') ?><input name="name" required maxlength="120" value="<?= View::e($editing['name']??'') ?>"></label><label><?= View::t('code') ?><input name="code" maxlength="60" value="<?= View::e($editing['code']??'') ?>"></label><label><?= View::t('parent_location') ?><select name="parent_id"><option value="">—</option><?php foreach($locations as $location): if($editing&&$location['id']===$editing['id'])continue; ?><option value="<?= View::e($location['id']) ?>" <?= ($editing['parent_id']??'')===$location['id']?'selected':'' ?>><?= View::e($location['name']) ?></option><?php endforeach; ?></select></label><label><?= View::t('spool_capacity') ?><input type="number" name="spool_capacity" min="1" max="999999" value="<?= View::e($editing['spool_capacity']??'') ?>"><small><?= View::t('spool_capacity_help') ?></small></label><label><?= View::t('description') ?><input name="description" maxlength="255" value="<?= View::e($editing['description']??'') ?>"></label><button class="action-button"><?= View::t('save') ?></button></form></section><?php endif; ?>
<section><div class="table-wrap"><table><thead><tr><th><?= View::t('name') ?></th><th><?= View::t('code') ?></th><th><?= View::t('parent_location') ?></th><th><?= View::t('spool_count') ?></th><th><?= View::t('space') ?></th><th></th></tr></thead><tbody><?php foreach($locations as $location): $capacity=$location['spool_capacity']!==null?(int)$location['spool_capacity']:null;$free=$capacity===null?null:max(0,$capacity-(int)$location['stored_count']); ?><tr><td><a class="button secondary-button action-button location-detail-button" href="<?= View::e($basePath) ?>/locations/<?= View::e($location['id']) ?>"><?= View::e($location['name']) ?></a></td><td><?= View::e($location['code']) ?></td><td><?= View::e($location['parent_name']??'—') ?></td><td><?= View::e($location['spool_count']) ?></td><td><?php if($capacity===null): ?><?= View::t('capacity_not_set') ?><?php elseif($free===0): ?><span class="inventory-full"><?= View::t('location_full') ?></span> · <?= View::e($location['stored_count']) ?>/<?= View::e($capacity) ?><?php else: ?><?= View::e($location['stored_count']) ?>/<?= View::e($capacity) ?> · <?= View::t('free_spaces',['count'=>$free]) ?><?php endif; ?></td><td><?php if($canManage): ?><div class="actions"><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/locations/<?= View::e($location['id']) ?>/edit"><?= View::t('edit') ?></a><form method="post" action="<?= View::e($basePath) ?>/locations/<?= View::e($location['id']) ?>/delete"><?= View::csrf() ?><button class="danger-button action-button"><?= View::t('delete') ?></button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
</div>
<section class="card warehouse-inventory"><h2><?= View::t('available_spools') ?></h2><p class="muted"><?= View::t('available_spools_help') ?></p><form method="get" action="<?= View::e($basePath) ?>/locations" class="filter-grid warehouse-filter-grid"><label><?= View::t('manufacturer') ?><select name="manufacturer"><option value=""><?= View::t('all') ?></option><?php foreach($inventoryFilters['manufacturers'] as $value=>$label): ?><option value="<?= View::e($value) ?>" <?= $inventoryFilters['selected']['manufacturer']===$value?'selected':'' ?>><?= View::e($label) ?></option><?php endforeach; ?></select></label><label><?= View::t('material') ?><select name="material_type"><option value=""><?= View::t('all') ?></option><?php foreach($inventoryFilters['types'] as $value): ?><option value="<?= View::e($value) ?>" <?= $inventoryFilters['selected']['material_type']===$value?'selected':'' ?>><?= View::e($value) ?></option><?php endforeach; ?></select></label><label><?= View::t('storage_location') ?><select name="location"><option value=""><?= View::t('all') ?></option><option value="__none__" <?= $inventoryFilters['selected']['location']==='__none__'?'selected':'' ?>><?= View::t('without_location') ?></option><?php foreach($inventoryFilters['locations'] as $value=>$label): ?><option value="<?= View::e($value) ?>" <?= $inventoryFilters['selected']['location']===$value?'selected':'' ?>><?= View::e($label) ?></option><?php endforeach; ?></select></label><label><?= View::t('color') ?><select name="color"><option value=""><?= View::t('all') ?></option><?php foreach($inventoryFilters['colors'] as $value): ?><option value="<?= View::e($value) ?>" <?= $inventoryFilters['selected']['color']===$value?'selected':'' ?>><?= View::e($value) ?></option><?php endforeach; ?></select></label><label><?= View::t('minimum_quantity') ?><input type="number" name="min_count" min="1" max="9999" value="<?= View::e($inventoryFilters['selected']['min_count']) ?>"></label><div class="filter-actions"><button class="action-button"><?= View::t('filter') ?></button><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/locations"><?= View::t('clear_filters') ?></a></div></form><div class="table-wrap warehouse-inventory-table"><table><thead><tr><th><?= View::t('material') ?></th><th><?= View::t('manufacturer') ?></th><th><?= View::t('color') ?></th><th><?= View::t('storage_location') ?></th><th><?= View::t('quantity') ?></th><th><?= View::t('total_remaining_weight') ?></th></tr></thead><tbody><?php foreach($inventoryGroups as $group): $hex=preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$group['color_hex'])?$group['color_hex']:'#d0d5dd'; ?><tr><td><strong><?= View::e($group['material_type']) ?></strong><?php if($group['commercial_name']): ?><br><small><?= View::e($group['commercial_name']) ?></small><?php endif; ?></td><td><?= View::e($group['manufacturer_name']?:'—') ?></td><td><input class="color-swatch" type="color" value="<?= View::e($hex) ?>" disabled> <?= View::e($group['color_name']) ?></td><td><?php if($group['location_id']): ?><a href="<?= View::e($basePath) ?>/locations/<?= View::e($group['location_id']) ?>"><?= View::e($group['location_name']) ?></a><?php else: ?><?= View::t('without_location') ?><?php endif; ?></td><td><strong><?= View::e($group['spool_count']) ?></strong></td><td><?= View::e(number_format((float)$group['total_weight_g'],0,',',' ')) ?> g</td></tr><?php endforeach; ?><?php if(!$inventoryGroups): ?><tr><td colspan="6"><?= View::t('no_available_spools') ?></td></tr><?php endif; ?></tbody></table></div></section>
